fn all_elements_equals(arr: &Vec<i32>, element: i32) -> bool {
    // Use the all method to check if all elements in the array equal the given element
    arr.iter().all(|&x| x == element)
}

fn main() {
    // Example usage
    let arr = vec![1, 1, 1];
    let element = 1;
    let result = all_elements_equals(&arr, element);
    println!("All elements equal {}: {}", element, result); // Should print true

    let arr2 = vec![1, 2, 1];
    let result2 = all_elements_equals(&arr2, element);
    println!("All elements equal {}: {}", element, result2); // Should print false

    let arr3: Vec<i32> = vec![];
    let result3 = all_elements_equals(&arr3, element);
    println!("All elements equal {}: {}", element, result3); // Should print true
}